const $=(s)=>document.querySelector(s);const lang=document.documentElement.lang;const game=document.body.dataset.game;const page=document.body.dataset.page;const labels={fr:{loading:'Chargement des données publiques…',offline:'Données en direct indisponibles actuellement.',none:'Aucune donnée publiée pour le moment.',driver:'Pilote',team:'Équipe',points:'Points',races:'Courses',wins:'Victoires',podiums:'Podiums',circuit:'Circuit',car:'Voiture',lap:'Meilleur tour',date:'Date',details:'Voir le profil',register:'Inscription',time:'Horaire',filters:'Catégorie',archive:'Résultats historiques du dépôt ACC',legacy:'Ouvrir le site ACC actuel'},en:{loading:'Loading public data…',offline:'Live data is currently unavailable.',none:'No published data yet.',driver:'Driver',team:'Team',points:'Points',races:'Races',wins:'Wins',podiums:'Podiums',circuit:'Circuit',car:'Car',lap:'Best lap',date:'Date',details:'View profile',register:'Register',time:'Schedule',filters:'Category',archive:'Historical results from the ACC repository',legacy:'Open the current ACC site'},de:{loading:'Öffentliche Daten werden geladen…',offline:'Live-Daten sind derzeit nicht verfügbar.',none:'Noch keine veröffentlichten Daten.',driver:'Fahrer',team:'Team',points:'Punkte',races:'Rennen',wins:'Siege',podiums:'Podestplätze',circuit:'Strecke',car:'Fahrzeug',lap:'Beste Runde',date:'Datum',details:'Profil ansehen',register:'Anmelden',time:'Zeitplan',filters:'Kategorie',archive:'Historische Ergebnisse aus dem ACC-Repository',legacy:'Aktuelle ACC-Seite öffnen'},it:{loading:'Caricamento dei dati pubblici…',offline:'Dati in tempo reale non disponibili.',none:'Nessun dato pubblicato.',driver:'Pilota',team:'Squadra',points:'Punti',races:'Gare',wins:'Vittorie',podiums:'Podi',circuit:'Circuito',car:'Auto',lap:'Miglior giro',date:'Data',details:'Vedi profilo',register:'Iscrizione',time:'Orario',filters:'Categoria',archive:'Risultati storici dal repository ACC',legacy:'Apri il sito ACC attuale'},es:{loading:'Cargando datos públicos…',offline:'Los datos en directo no están disponibles.',none:'Todavía no hay datos publicados.',driver:'Piloto',team:'Equipo',points:'Puntos',races:'Carreras',wins:'Victorias',podiums:'Podios',circuit:'Circuito',car:'Coche',lap:'Mejor vuelta',date:'Fecha',details:'Ver perfil',register:'Inscripción',time:'Horario',filters:'Categoría',archive:'Resultados históricos del repositorio ACC',legacy:'Abrir el sitio ACC actual'}}[lang]||{};const siteBase=document.querySelector('meta[name=atx-base]')?.content||'/';const base=siteBase+lang+'/'+game+'/';const api='https://twjpjzalyvbsdpbzhqln.supabase.co/functions/v1';function node(tag,cls,content){const el=document.createElement(tag);if(cls)el.className=cls;if(content!=null)el.textContent=String(content);return el}function link(text,href){const a=node('a','pill',text);a.href=href;return a}function safeExternal(url){try{const u=new URL(url);return u.protocol==='https:'?u.href:null}catch{return null}}function date(s){return s?new Intl.DateTimeFormat(lang,{dateStyle:'medium',timeStyle:'short',timeZone:'Europe/Brussels'}).format(new Date(s)):'—'}function lap(ms){const n=Number(ms);return n>0?`${Math.floor(n/60000)}:${String(Math.floor(n/1000)%60).padStart(2,'0')}.${String(n%1000).padStart(3,'0')}`:'—'}function table(headers,rows){const outer=node('div','table-wrap'),t=node('table'),thead=node('thead'),tr=node('tr');headers.forEach(x=>tr.append(node('th','',x)));thead.append(tr);t.append(thead);const body=node('tbody');rows.forEach(row=>{const tr=node('tr');row.forEach(v=>{const cell=node('td');if(v instanceof Node)cell.append(v);else cell.textContent=String(v??'—');tr.append(cell)});body.append(tr)});t.append(body);outer.append(t);return outer}function status(text){const root=$('#results');root.replaceChildren(node('p','empty',text))}async function get(path){const r=await fetch(api+path,{signal:AbortSignal.timeout(10000)});if(!r.ok)throw Error(r.status);return r.json()}function profileLink(d){return d.profile_id?link(d.display_name||'—',base+'profile.html?driver='+encodeURIComponent(d.profile_id)):node('span','',d.display_name||'—')}async function events(){const root=$('#results');if(game==='ace'){status(labels.none);return}try{const d=await get('/public-event');const items=d.events||[];if(!items.length)return status(labels.none);root.replaceChildren();const grid=node('div','grid');items.forEach(e=>{const card=node('article','panel');card.append(node('span','meta',e.event_type||'ACC'),node('h3','',e['title_'+lang]||e.title_en||e.title_fr||e.circuit_name),node('p','',e.circuit_name+' · '+date(e.starts_at)));const u=safeExternal(e.simgrid_url);if(u){const a=link(labels.register,u);a.target='_blank';a.rel='noopener noreferrer';card.append(a)}grid.append(card)});root.append(grid)}catch{status(labels.offline)}}function historical(root){const note=node('div','panel');note.append(node('span','meta',labels.archive),node('h3','','Monza · 1 septembre 2026'));const a=link(labels.legacy,'https://athoxmotorsport-lab.github.io/atx-racing/archives.html');note.append(a);root.append(note)}async function rankings(){if(game==='ace')return status(labels.none);const type=$('#category')?.value||'DR';const root=$('#results');root.replaceChildren(node('p','loading',labels.loading));try{const d=await get('/public-leaderboard?category='+encodeURIComponent(type));const drivers=(d.drivers||[]).map(x=>[x.rank,profileLink(x),x.team_name||'—',x.primary_car||'—',x.races,x.wins,x.podiums,x.points]);const highlights=$('#ranking-highlights');if(highlights){highlights.replaceChildren();(d.drivers||[]).slice(0,3).forEach((x,i)=>{const card=node('article','podium-card');card.append(node('span','meta','#'+(x.rank||i+1)+' / '+type),node('h3','',x.display_name||'—'),node('p','',x.team_name||'—'),node('b','',String(x.points??0)+' '+labels.points));highlights.append(card)})}root.replaceChildren(drivers.length?table(['#',labels.driver,labels.team,labels.car,labels.races,labels.wins,labels.podiums,labels.points],drivers):node('p','empty',labels.none))}catch{status(labels.offline)}}async function records(){
 const root=$('#results'),grid=$('#circuit-grid'),spot=$('#record-spotlight');
 root.replaceChildren(node('p','loading',labels.loading));
 const fallback={fr:'Aucun chrono',en:'No lap time',de:'Noch keine Rundenzeit',it:'Nessun tempo',es:'Sin tiempos'}[lang]||labels.none;
 const normal=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'_').replace(/^_+|_+$/g,'');
 const aliases={circuit_of_the_americas:'cota',nurburgring_gp:'nurburgring',spa_francorchamps:'spa',donington_park:'donington'};
 const titles={barcelona:'Barcelona',brands_hatch:'Brands Hatch',cota:'Circuit of the Americas',donington:'Donington Park',hungaroring:'Hungaroring',imola:'Imola',indianapolis:'Indianapolis',kyalami:'Kyalami',laguna_seca:'Laguna Seca',misano:'Misano',monza:'Monza',mount_panorama:'Mount Panorama',nurburgring:'Nürburgring GP',nurburgring_24h:'Nürburgring 24h',oulton_park:'Oulton Park',paul_ricard:'Paul Ricard',red_bull_ring:'Red Bull Ring',silverstone:'Silverstone',snetterton:'Snetterton',spa:'Spa-Francorchamps',suzuka:'Suzuka',valencia:'Valencia',watkins_glen:'Watkins Glen',zandvoort:'Zandvoort',zolder:'Zolder'};
 try{
  const payload=await get('/public-leaderboard?category=ALL');
  const indexed=new Map((payload.circuits||[]).map(c=>[aliases[normal(c.circuit_key||c.circuit_name)]||normal(c.circuit_key||c.circuit_name),c]));
  const visual=typeof ATX_CIRCUITS==='object'?ATX_CIRCUITS:{};
  const keys=[...Object.keys(titles),...indexed.keys()].filter((key,index,all)=>all.indexOf(key)===index);
  grid.replaceChildren();
  function select(key){
   grid.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.key===key)));
   const c=indexed.get(key),best=c?.drivers?.[0];
   spot.replaceChildren();
   if(c){spot.append(node('span','meta',c.circuit_name),node('strong','',lap(c.reference_lap_ms)),node('span','',c.reference_driver||'—'))}
   root.replaceChildren(c?.drivers?.length?table(['#',labels.driver,labels.car,labels.lap,labels.date],c.drivers.map((d,i)=>[i+1,profileLink(d),d.car_model_name||'—',lap(d.best_lap_ms),date(d.achieved_at)])):node('p','empty',fallback));
  }
  keys.forEach(key=>{
   const c=indexed.get(key),v=visual[key],card=node('button','record-card');card.type='button';card.dataset.key=key;
   const media=node('span','record-photo');
   if(v?.image){const photo=node('img');photo.src=v.image;photo.alt='';photo.loading='lazy';photo.referrerPolicy='no-referrer';photo.onerror=()=>photo.remove();media.append(photo)}
   if(v?.country)media.append(node('span','record-country',v.country));
   const body=node('span','record-copy');body.append(node('strong','',titles[key]||c?.circuit_name||key.replaceAll('_',' ')),node('small','',c?.reference_driver||''),node('b','',c?.reference_lap_ms?lap(c.reference_lap_ms):fallback));
   card.append(media,body);card.onclick=()=>select(key);grid.append(card)
  });
  root.replaceChildren();select(keys.find(k=>indexed.get(k)?.drivers?.length)||keys[0]);
 }catch{grid.replaceChildren();spot.replaceChildren();status(labels.offline)}
}
async function directory(){const root=$('#results'),input=$('#driver-search');root.replaceChildren(node('p','loading',labels.loading));try{const d=await get('/public-leaderboard?category=ALL');const drivers=d.drivers||[];const render=()=>{const q=(input?.value||'').toLocaleLowerCase(lang).trim();const matches=drivers.filter(x=>(x.display_name+' '+(x.team_name||'')).toLocaleLowerCase(lang).includes(q));root.replaceChildren(matches.length?table(['#',labels.driver,labels.team,labels.races,labels.wins,labels.points],matches.map((x,i)=>[i+1,profileLink(x),x.team_name||'—',x.races,x.wins,x.points])):node('p','empty',labels.none))};if(input)input.oninput=render;render()}catch{status(labels.offline)}}async function profile(){
 const id=new URLSearchParams(location.search).get('driver');if(!id)return directory();
 const root=$('#results');root.replaceChildren(node('p','loading',labels.loading));
 const ui={fr:{performance:'Performance',safe:'SAFE',about:'Présentation',history:'Résultats',best:'Chronos personnels',awards:'Distinctions',private:'Ce profil public n’est pas disponible.'},en:{performance:'Performance',safe:'SAFE',about:'About',history:'Results',best:'Personal best laps',awards:'Honours',private:'This public profile is unavailable.'},de:{performance:'Leistung',safe:'SAFE',about:'Vorstellung',history:'Ergebnisse',best:'Persönliche Bestzeiten',awards:'Auszeichnungen',private:'Dieses öffentliche Profil ist nicht verfügbar.'},it:{performance:'Prestazione',safe:'SAFE',about:'Presentazione',history:'Risultati',best:'Giri migliori personali',awards:'Riconoscimenti',private:'Questo profilo pubblico non è disponibile.'},es:{performance:'Rendimiento',safe:'SAFE',about:'Presentación',history:'Resultados',best:'Mejores vueltas personales',awards:'Distinciones',private:'Este perfil público no está disponible.'}}[lang];
 try{
  const d=(await get('/public-driver?driver='+encodeURIComponent(id))).driver;
  const card=node('article','public-driver-card'),top=node('div','public-driver-top');
  const avatar=node('span','account-avatar',(d.display_name||'AT').slice(0,2).toUpperCase());
  if(d.avatar_url&&safeExternal(d.avatar_url)){const img=node('img');img.src=d.avatar_url;img.alt='';img.referrerPolicy='no-referrer';img.onerror=()=>img.remove();avatar.replaceChildren(img)}
  const identity=node('div');identity.append(node('span','eyebrow',d.team_name||'ATXRACING'),node('h2','',d.display_name));if(d.country_code)identity.append(node('small','',d.country_code));top.append(avatar,identity);card.append(top);
  const overall=(d.ratings||[]).find(r=>r.circuit_key==='overall');if(overall){const badges=node('div','account-badges');badges.append(node('span','',ui.performance+' · '+String(overall.performance_class||'—').toUpperCase()+(overall.performance_score!=null?' · '+Number(overall.performance_score).toFixed(2)+'%':'')),node('span','',ui.safe+' · '+String(overall.safety_class||'—').toUpperCase()+(overall.safety_score!=null?' · '+Math.round(overall.safety_score)+'/100':'')));card.append(badges)}
  const bio=d['bio_'+lang]||d.bio_en||d.bio_fr;if(bio)card.append(node('p','driver-bio',bio));
  const stats=node('div','account-stats');[[labels.races,d.stats?.races],[labels.wins,d.stats?.wins],[labels.podiums,d.stats?.podiums],[labels.points,d.stats?.points]].forEach(([key,value])=>{const stat=node('div');stat.append(node('b','',value??0),node('small','',key));stats.append(stat)});card.append(stats);
  const socials=node('div','driver-socials');[['Twitch',d.twitch_url],['TikTok',d.tiktok_url],['YouTube',d.youtube_url],['Web',d.website_url]].forEach(([name,url])=>{const safe=safeExternal(url);if(safe){const a=link(name,safe);a.target='_blank';a.rel='noopener noreferrer';socials.append(a)}});card.append(socials);root.replaceChildren(card);
  if(d.awards?.length){root.append(node('h2','public-section-title',ui.awards));const awards=node('div','driver-awards');d.awards.forEach(a=>awards.append(node('span','pill',String(a.award_type||'ATX').replaceAll('_',' '))));root.append(awards)}
  if(d.results?.length){root.append(node('h2','public-section-title',ui.history),table([labels.date,labels.circuit,labels.car,labels.points,labels.lap],d.results.map(r=>[date(r.event?.starts_at),r.event?.circuit_name||'—',r.car_model_name||'—',r.points,lap(r.best_lap_ms)])))}
  try{const sectorPayload=await get('/public-driver-sectors');const laps=(sectorPayload.sectors||[]).filter(x=>x.driver_id===id&&x.best_lap_ms>0);if(laps.length){root.append(node('h2','public-section-title',ui.best),table([labels.circuit,labels.lap,labels.date],laps.map(x=>[x.circuit_name,lap(x.best_lap_ms),date(x.best_lap_at)])))}}catch{}
 }catch{root.replaceChildren(node('p','empty',ui.private))}
}
if(page==='courses')events();if(page==='ranking'){rankings();$('#category').onchange=rankings}if(page==='records')records();if(page==='profile')profile();
